class Solution {
public:
    int getMinimumDifference(TreeNode* root) {
        int ans = INT_MAX;
        TreeNode* prev = nullptr;
        TreeNode* cur = root;
        while (cur != nullptr) {
            if (cur->left == nullptr) {
                if (prev != nullptr) {
                    int d = cur->val - prev->val;
                    if (d < ans) ans = d;
                }
                prev = cur;
                cur = cur->right;
            } else {
                TreeNode* pred = cur->left;
                while (pred->right != nullptr && pred->right != cur) {
                    pred = pred->right;
                }
                if (pred->right == nullptr) {
                    pred->right = cur;
                    cur = cur->left;
                } else {
                    pred->right = nullptr;
                    if (prev != nullptr) {
                        int d = cur->val - prev->val;
                        if (d < ans) ans = d;
                    }
                    prev = cur;
                    cur = cur->right;
                }
            }
        }
        return ans;
    }
};
